import{_ as t,o as e,c as a,ae as n}from"./chunks/framework.Dzr56EFm.js";const c=JSON.parse('{"title":"设计趋势 - 2026-05-12","description":"","frontmatter":{"date":"2026-05-12T00:00:00.000Z","category":"UX Trend"},"headers":[],"relativePath":"daily/2026-05-12-uxtrend.md","filePath":"daily/2026-05-12-uxtrend.md"}'),o={name:"daily/2026-05-12-uxtrend.md"};function s(i,r,g,p,h,l){return e(),a("div",null,[...r[0]||(r[0]=[n('<h1 id="设计趋势-2026-05-12" tabindex="-1">设计趋势 - 2026-05-12 <a class="header-anchor" href="#设计趋势-2026-05-12" aria-label="Permalink to &quot;设计趋势 - 2026-05-12&quot;">​</a></h1><blockquote><p>AI交互方式、Prompt UX、Agent UX、Workflow</p></blockquote><h2 id="今日概览" tabindex="-1">今日概览 <a class="header-anchor" href="#今日概览" aria-label="Permalink to &quot;今日概览&quot;">​</a></h2><p>今日设计趋势资讯聚焦于AI在工作流程中的应用和代理式用户体验。主要动态包括AI工作流的优化技巧、产品设计师如何融入AI工具、为代理系统设计的7原则、AI代理工作流设计模式探讨以及AI代理对数字体验的影响。最值得关注的是AI工具在提升设计效率和用户体验方面的巨大潜力。</p><hr><h3 id="_1-ai工作流优化-7个实用技巧" tabindex="-1">1. AI工作流优化：7个实用技巧 <a class="header-anchor" href="#_1-ai工作流优化-7个实用技巧" aria-label="Permalink to &quot;1. AI工作流优化：7个实用技巧&quot;">​</a></h3><p><strong>原文标题</strong>: <a href="https://medium.com/@vicki-larson/ai-workflow-optimization-7-game-changing-tips-that-actually-work-414862126f5f" target="_blank" rel="noreferrer">AI Workflow Optimization: 7 Game-Changing Tips That Actually Work</a></p><p><strong>一句话摘要</strong>: 利用AI工具优化设计工作流程，提升效率</p><p><strong>能解决什么问题</strong>: 设计工作流程效率低下，难以系统化</p><p><strong>产品应用</strong>: 适用于需要提升设计效率和质量的产品开发团队</p><p><strong>示例场景</strong>: 设计师使用AI工具生成布局结构和配色方案</p><hr><h3 id="_2-产品设计师如何将ai融入设计工作流程" tabindex="-1">2. 产品设计师如何将AI融入设计工作流程 <a class="header-anchor" href="#_2-产品设计师如何将ai融入设计工作流程" aria-label="Permalink to &quot;2. 产品设计师如何将AI融入设计工作流程&quot;">​</a></h3><p><strong>原文标题</strong>: <a href="https://medium.com/@mariamargarida/ai-in-my-design-workflow-as-a-product-designer-feb120d8fe38" target="_blank" rel="noreferrer">AI In My Design Workflow As a Product Designer</a></p><p><strong>一句话摘要</strong>: AI工具V0在产品设计师工作流程中的应用与优势</p><p><strong>能解决什么问题</strong>: 解决复杂设计流程中的快速原型制作和交互演示问题</p><p><strong>产品应用</strong>: 适用于需要快速迭代和演示的产品设计工作，尤其是在短流程交互中</p><p><strong>示例场景</strong>: 使用V0快速创建滚动行为和过渡效果的原型</p><hr><h3 id="_3-代理式用户体验-为代理系统设计7原则" tabindex="-1">3. 代理式用户体验：为代理系统设计7原则 <a class="header-anchor" href="#_3-代理式用户体验-为代理系统设计7原则" aria-label="Permalink to &quot;3. 代理式用户体验：为代理系统设计7原则&quot;">​</a></h3><p><strong>原文标题</strong>: <a href="https://medium.com/design-bootcamp/agentic-ux-7-principles-for-designing-systems-with-agents-019512c2caa9" target="_blank" rel="noreferrer">Agentic UX: 7 principles for designing systems with agents</a></p><p><strong>一句话摘要</strong>: 设计代理系统时，需考虑上下文共享和信息流动。</p><p><strong>能解决什么问题</strong>: 解决代理行为与用户期望不一致导致的不信任问题。</p><p><strong>产品应用</strong>: 适用于需要代理自动化处理任务的产品，如配置或设置屏幕。</p><p><strong>示例场景</strong>: 自动更新规则时，提供撤销选项和简短解释。</p><hr><h3 id="_4-ai代理工作流设计模式概览" tabindex="-1">4. AI代理工作流设计模式概览 <a class="header-anchor" href="#_4-ai代理工作流设计模式概览" aria-label="Permalink to &quot;4. AI代理工作流设计模式概览&quot;">​</a></h3><p><strong>原文标题</strong>: <a href="https://medium.com/binome/ai-agent-workflow-design-patterns-an-overview-cf9e1f609696" target="_blank" rel="noreferrer">AI Agent Workflow Design Patterns — An Overview</a></p><p><strong>一句话摘要</strong>: 探讨基于大型语言模型的AI代理工作流设计模式。</p><p><strong>能解决什么问题</strong>: 如何通过AI代理有效执行复杂任务和决策。</p><p><strong>产品应用</strong>: 可以应用到需要自动化决策和执行的智能系统。</p><p><strong>示例场景</strong>: 自动化制作咖啡流程的设计和执行。</p><hr><h3 id="_5-代理型用户体验时代-数字体验的未来" tabindex="-1">5. 代理型用户体验时代：数字体验的未来 <a class="header-anchor" href="#_5-代理型用户体验时代-数字体验的未来" aria-label="Permalink to &quot;5. 代理型用户体验时代：数字体验的未来&quot;">​</a></h3><p><strong>原文标题</strong>: <a href="https://uxdesign.cc/the-agentic-era-of-ux-4b58634e410b" target="_blank" rel="noreferrer">The agentic era of UX. The future of digital experience is… | by Alex Klein | UX Collective</a></p><p><strong>一句话摘要</strong>: AI代理在认知、创意和后勤三方面助力用户体验。</p><p><strong>能解决什么问题</strong>: 解决用户在数字体验中需要独立思考、规划和导航的问题。</p><p><strong>产品应用</strong>: 可应用于产品设计，通过AI代理减轻用户负担，提升体验。</p><p><strong>示例场景</strong>: Adobe的Gen Studio通过AI代理辅助用户创作。</p><hr><h3 id="_6-顶级公司如何将人工智能应用于设计工作流程" tabindex="-1">6. 顶级公司如何将人工智能应用于设计工作流程 <a class="header-anchor" href="#_6-顶级公司如何将人工智能应用于设计工作流程" aria-label="Permalink to &quot;6. 顶级公司如何将人工智能应用于设计工作流程&quot;">​</a></h3><p><strong>原文标题</strong>: <a href="https://uxdesign.cc/how-top-companies-are-using-ai-in-their-design-workflows-d10ec40fb6af" target="_blank" rel="noreferrer">How top companies are using AI in their design workflows</a></p><p><strong>一句话摘要</strong>: 顶级公司正在使用AI优化设计工作流程。</p><p><strong>能解决什么问题</strong>: 解决设计流程中的效率和测试速度问题。</p><p><strong>产品应用</strong>: 可以应用到产品中，通过AI加速设计和测试过程。</p><p><strong>示例场景</strong>: Atlassian使用AI设计到原型工作流程。</p><hr><h3 id="_7-从产品到系统-代理性ai的转变" tabindex="-1">7. 从产品到系统：代理性AI的转变 <a class="header-anchor" href="#_7-从产品到系统-代理性ai的转变" aria-label="Permalink to &quot;7. 从产品到系统：代理性AI的转变&quot;">​</a></h3><p><strong>原文标题</strong>: <a href="https://uxdesign.cc/from-products-to-systems-the-agentic-ai-shift-eaf6a7180c43" target="_blank" rel="noreferrer">From products to systems: The agentic AI shift | by John Moriarty | UX Collective</a></p><p><strong>一句话摘要</strong>: 设计需适应人类与代理协作的新需求。</p><p><strong>能解决什么问题</strong>: 如何确保在代理主导的体验中保持设计质量、一致性和可访问性。</p><p><strong>产品应用</strong>: 适用于需要自动化和智能化设计流程的企业平台，通过编码设计标准实现。</p><p><strong>示例场景</strong>: 企业平台通过代理生成界面，保持品牌一致性和可访问性。</p><hr><h3 id="_8-ai设计模式-构建模块化机器学习管道和代理系统" tabindex="-1">8. AI设计模式：构建模块化机器学习管道和代理系统 <a class="header-anchor" href="#_8-ai设计模式-构建模块化机器学习管道和代理系统" aria-label="Permalink to &quot;8. AI设计模式：构建模块化机器学习管道和代理系统&quot;">​</a></h3><p><strong>原文标题</strong>: <a href="https://medium.com/@shahriddhi717/ai-design-patterns-engineering-modular-ml-pipelines-and-agentic-systems-c5f9f7ca29db" target="_blank" rel="noreferrer">AI Design Patterns: Engineering Modular ML Pipelines and Agentic Systems</a></p><p><strong>一句话摘要</strong>: AI设计模式提供了解决AI系统开发中常见挑战的架构解决方案。</p><p><strong>能解决什么问题</strong>: 解决AI系统开发中的模型训练、推理管道和代理行为等独特问题。</p><p><strong>产品应用</strong>: 可应用于构建可维护、自动化的机器学习工作流和自主语言模型代理。</p><p><strong>示例场景</strong>: 在构建自动化客户服务聊天机器人时应用代理设计模式。</p><hr><h3 id="_9-ai-ux-人工智能代理的体验设计" tabindex="-1">9. AI/UX：人工智能代理的体验设计 <a class="header-anchor" href="#_9-ai-ux-人工智能代理的体验设计" aria-label="Permalink to &quot;9. AI/UX：人工智能代理的体验设计&quot;">​</a></h3><p><strong>原文标题</strong>: <a href="https://medium.com/i-ux/ai-ux-experience-design-of-ai-agents-12e1051fa065" target="_blank" rel="noreferrer">AI/UX: Experience Design of AI Agents</a></p><p><strong>一句话摘要</strong>: AI代理通过学习提升服务能力，成为服务生态系统的活跃参与者。</p><p><strong>能解决什么问题</strong>: 解决传统UX设计中无法适应AI代理需求的问题。</p><p><strong>产品应用</strong>: 可应用于智能助手、聊天机器人等，通过API和数据结构优化交互。</p><p><strong>示例场景</strong>: 智能助手根据用户习惯自动安排会议和日程。</p><hr><h3 id="_10-转向代理型ux-为我思考" tabindex="-1">10. 转向代理型UX：为我思考 <a class="header-anchor" href="#_10-转向代理型ux-为我思考" aria-label="Permalink to &quot;10. 转向代理型UX：为我思考&quot;">​</a></h3><p><strong>原文标题</strong>: <a href="https://medium.com/@dirkjankraan/the-shift-to-agentic-ux-do-the-thinking-for-me-55b68b289de9" target="_blank" rel="noreferrer">The shift to agentic UX: do the thinking for me</a></p><p><strong>一句话摘要</strong>: 探讨如何利用AI代理改善用户体验，减少用户操作摩擦。</p><p><strong>能解决什么问题</strong>: 解决用户在使用软件时的思考和操作障碍。</p><p><strong>产品应用</strong>: 可以应用于B2B门户等产品，通过AI代理减少用户操作步骤。</p><p><strong>示例场景</strong>: B2B门户通过AI代理提供个性化用户指导。</p><hr>',75)])])}const f=t(o,[["render",s]]);export{c as __pageData,f as default};
